# Headless build + test harness (no GUI window).
# Usage: powershell -File scripts\harness.ps1 [-NoBuild] [-NoGtest] [-Full] [-BenchIters 2000]
# Logs go to build\harness\ (git root); exit code 1 if any step fails.
param([switch]$NoBuild, [switch]$NoGtest, [switch]$Full, [int]$BenchIters = 2000)

$root = Split-Path -Parent $PSScriptRoot
$src = Join-Path $root 'opti_chess'
$bin = Join-Path $src 'build\windows-release\Release'
$logs = Join-Path $root 'build\harness'
New-Item -ItemType Directory -Force $logs | Out-Null
$failed = @()

# The build tree is generated by Visual Studio 18: its own cmake must drive it
$cmake = 'C:\Program Files\Microsoft Visual Studio\18\Insiders\Common7\IDE\CommonExtensions\Microsoft\CMake\CMake\bin\cmake.exe'
if (-not (Test-Path $cmake)) { $cmake = 'cmake' }

if (-not $NoBuild) {
    Get-Process opti_chess* -ErrorAction SilentlyContinue | Stop-Process -Force
    # Tests + GUI + CLI in ONE command from the same tree (paired build rule, AGENTS.md)
    & $cmake --build (Join-Path $src 'build\windows-release') --config Release `
        --target opti_chess_tests opti_chess opti_chess_cli -- /m /v:minimal *> (Join-Path $logs 'build.log')
    if ($LASTEXITCODE -ne 0) { Write-Host 'BUILD FAILED (see build.log)'; exit 1 }
    Write-Host 'build OK'
}

$cli = Join-Path $bin 'opti_chess_cli.exe'
Push-Location $src
try {
    $mode = if ($Full) { 'full' } else { 'quick' }
    & $cli perft-suite $mode *> (Join-Path $logs 'perft.log')
    if ($LASTEXITCODE -ne 0) { $failed += 'perft' }
    Get-Content (Join-Path $logs 'perft.log') | Select-Object -Last 2

    if (-not $NoGtest) {
        # Same exclusions as CI (.github/workflows/build.yml): wall-clock benchmarks stay manual
        $neg = '-*Debug*:*Perf*:*LichessBenchmark*:*CalibratedBatch*:*TestsTxtBatch*:*TimeBudgetLadder*:*ScalingBenchmark*:*TimeBenchmark*:*GuiLikeBench*:*ParamSweep*:*OFFvsDAG*'
        & (Join-Path $bin 'opti_chess_tests.exe') "--gtest_filter=$neg" *> (Join-Path $logs 'gtest.log')
        if ($LASTEXITCODE -ne 0) { $failed += 'gtest' }
        Get-Content (Join-Path $logs 'gtest.log') | Where-Object { $_ -match '^\[  (PASSED|FAILED) ' }
    }

    $session = "uci`nisready`nposition startpos moves e2e4 e7e5`ngo nodes 500`nposition fen 4k3/8/8/K2pP2r/8/8/8/8 w - d6 0 1`ngo nodes 200`nquit`n"
    $session | & $cli uci *> (Join-Path $logs 'uci.log')
    $uci = Get-Content (Join-Path $logs 'uci.log')
    if (-not ($uci -contains 'uciok') -or @($uci | Where-Object { $_ -like 'bestmove *' }).Count -ne 2 -or ($uci -contains 'bestmove e5d6')) { $failed += 'uci' }
    Write-Host ("uci: " + (($uci | Where-Object { $_ -like 'bestmove *' }) -join ', '))

    & $cli bench $BenchIters *> (Join-Path $logs 'bench.log')
    if ($LASTEXITCODE -ne 0) { $failed += 'bench' }
    Get-Content (Join-Path $logs 'bench.log') | Select-Object -Last 2
}
finally { Pop-Location }

if ($failed.Count) { Write-Host "FAILED: $($failed -join ', ')"; exit 1 }
Write-Host 'ALL OK'
